<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { getAccessToken } from '@/services/api-client'
import { getMarketStocks } from '@/services/market'
import type { StockQuote } from '@/services/market-types'
import EmptyState from '@/components/EmptyState.vue'
import LoadingState from '@/components/LoadingState.vue'
import { useWatchlistStore } from '@/stores/watchlist'

const watchlist = useWatchlistStore()
const stocks = ref<StockQuote[]>([])
const activeId = ref('default')
const selected = ref<string[]>([])
const loading = ref(true)
const error = ref('')
const editing = ref(false)
const draggedGroup = ref<string | null>(null)
const draggedCode = ref<string | null>(null)
const dialog = ref<'create' | 'rename' | null>(null)
const draftName = ref('')

const stockMap = computed(() => new Map(stocks.value.map((stock) => [stock.code, stock])))
const groups = computed(() => [{ id: 'default', name: '默认自选', sortOrder: -1 }, ...watchlist.groups.value])
const activeGroup = computed(() => groups.value.find((group) => group.id === activeId.value) ?? groups.value[0])
const activeItems = computed(() => watchlist.itemsByGroup.value[activeId.value] ?? [])
const activeStocks = computed(() => activeItems.value.map((item) => stockMap.value.get(item.code)).filter((stock): stock is StockQuote => Boolean(stock)))
const selectedAll = computed(() => activeStocks.value.length > 0 && activeStocks.value.every((stock) => selected.value.includes(stock.code)))
const totalCount = computed(() => groups.value.reduce((sum, group) => sum + itemCount(group.id), 0))
const stats = computed(() => ({ up: activeStocks.value.filter((stock) => stock.trend === 'up').length, down: activeStocks.value.filter((stock) => stock.trend === 'down').length }))
const isLocal = computed(() => !getAccessToken())

function itemCount(id: string) { return (watchlist.itemsByGroup.value[id] ?? []).length }
function groupStats(id: string) { const list = (watchlist.itemsByGroup.value[id] ?? []).map((item) => stockMap.value.get(item.code)); return { count: list.length, up: list.filter((stock) => stock?.trend === 'up').length, down: list.filter((stock) => stock?.trend === 'down').length } }
async function load() { loading.value = true; error.value = ''; try { await Promise.all([watchlist.hydrate(), getMarketStocks().then((data) => { stocks.value = data })]) } catch { error.value = '数据加载失败，请重试。' } finally { loading.value = false } }
function selectGroup(id: string) { activeId.value = id; selected.value = []; editing.value = false }
function openCreate() { draftName.value = ''; dialog.value = 'create' }
function openRename() { if (activeId.value !== 'default') { draftName.value = activeGroup.value.name; dialog.value = 'rename' } }
async function saveDialog() { const name = draftName.value.trim(); if (!name) return; if (dialog.value === 'create') { const group = await watchlist.createGroup(name); selectGroup(group.id) } else if (dialog.value === 'rename') await watchlist.renameGroup(activeId.value, name); dialog.value = null }
async function deleteActive() { if (activeId.value === 'default') return; if (window.confirm(`删除“${activeGroup.value.name}”？其中股票会回到默认自选。`)) { await watchlist.deleteGroup(activeId.value); selectGroup('default') } }
function toggle(code: string) { selected.value = selected.value.includes(code) ? selected.value.filter((item) => item !== code) : [...selected.value, code] }
function toggleAll() { selected.value = selectedAll.value ? [] : activeStocks.value.map((stock) => stock.code) }
async function moveSelected(event: Event) { const target = (event.target as HTMLSelectElement).value; if (!target || !selected.value.length) return; for (const code of selected.value) await watchlist.move(code, target === 'default' ? null : target); selected.value = [] }
async function deleteSelected() { if (!selected.value.length) return; await watchlist.removeBatch(selected.value, activeId.value === 'default' ? null : activeId.value); selected.value = [] }
async function dropGroup(id: string) { if (draggedCode.value && id !== activeId.value) { for (const code of selected.value.length ? selected.value : [draggedCode.value]) await watchlist.move(code, id === 'default' ? null : id); selected.value = [] } else if (draggedGroup.value && draggedGroup.value !== id) { const ids = watchlist.groups.value.map((group) => group.id); const from = ids.indexOf(draggedGroup.value); const to = ids.indexOf(id); if (from >= 0 && to >= 0) { ids.splice(from, 1); ids.splice(to, 0, draggedGroup.value); await watchlist.reorderGroups(ids) } } draggedCode.value = null; draggedGroup.value = null }
async function dropStock(index: number) { if (!draggedCode.value) return; const codes = activeItems.value.map((item) => item.code).filter((code) => code !== draggedCode.value); codes.splice(index, 0, draggedCode.value); await watchlist.reorder(activeId.value === 'default' ? null : activeId.value, codes); draggedCode.value = null }
function quoteClass(stock: StockQuote) { return stock.trend === 'up' ? 'text-up' : 'text-down' }
onMounted(load)
</script>

<template>
  <section class="groups-page">
    <header class="page-head"><div><p class="eyebrow">WATCHLIST · ORGANIZE</p><h1>自选分组</h1><p class="subtitle">按策略整理关注标的，拖动即可调整顺序</p></div><div class="head-actions"><span class="source-badge" :class="{ local: isLocal }">{{ isLocal ? '本地保存' : '已同步' }}</span><button class="refresh" :disabled="loading" @click="load">↻</button></div></header>
    <section class="overview"><div><span>全部分组</span><strong>{{ groups.length }}</strong></div><div><span>关注标的</span><strong>{{ totalCount }}</strong></div><div><span>当前上涨</span><strong class="text-up">{{ stats.up }}</strong></div><div><span>当前下跌</span><strong class="text-down">{{ stats.down }}</strong></div></section>
    <LoadingState v-if="loading" label="正在加载自选分组" /><p v-else-if="error" class="error">{{ error }} <button @click="load">重试</button></p>
    <div v-else class="workspace"><aside class="group-panel"><div class="panel-title"><div><p>GROUPS</p><h2>我的分组</h2></div><button class="primary-small" @click="openCreate">＋ 新建</button></div><p class="drag-tip">拖动分组可调整顺序</p><div class="group-list"><button v-for="group in groups" :key="group.id" class="group-card" :class="{ active: activeId === group.id }" draggable="true" @click="selectGroup(group.id)" @dragstart="draggedGroup = group.id" @dragover.prevent @drop.prevent="dropGroup(group.id)"><span class="drag-handle">⠿</span><span class="group-mark">{{ group.id === 'default' ? '☆' : '▦' }}</span><span class="group-copy"><strong>{{ group.name }}</strong><small>{{ groupStats(group.id).count }} 个标的 · <i class="text-up">{{ groupStats(group.id).up }} 涨</i> <i class="text-down">{{ groupStats(group.id).down }} 跌</i></small></span><b class="group-arrow">›</b></button></div><RouterLink class="market-link" to="/market">去行情添加股票 <span>›</span></RouterLink></aside>
      <main class="stock-panel"><header class="stock-heading"><div><p class="eyebrow">ACTIVE GROUP</p><h2>{{ activeGroup.name }}</h2><p>{{ activeItems.length }} 个标的 · <span class="text-up">{{ stats.up }} 上涨</span> · <span class="text-down">{{ stats.down }} 下跌</span></p></div><div class="group-actions"><button v-if="activeId !== 'default'" @click="openRename">重命名</button><button v-if="activeId !== 'default'" class="danger" @click="deleteActive">删除</button><button class="edit" @click="editing = !editing; selected = []">{{ editing ? '完成' : '批量管理' }}</button></div></header><div class="toolbar"><button :class="{ active: !editing }" @click="editing = false; selected = []">浏览</button><button :class="{ active: editing }" @click="editing = true">批量操作</button><span class="toolbar-note">拖动股票可排序</span></div><div v-if="editing" class="batch-bar"><button @click="toggleAll">{{ selectedAll ? '取消全选' : '全选' }}</button><span>已选 {{ selected.length }} 项</span><select :disabled="!selected.length" @change="moveSelected"><option value="">移动到…</option><option v-for="group in groups" :key="group.id" :value="group.id" :disabled="group.id === activeId">{{ group.name }}</option></select><button class="danger" :disabled="!selected.length" @click="deleteSelected">批量移除</button></div><div v-if="activeStocks.length" class="stock-list"><RouterLink v-for="(stock, index) in activeStocks" :key="stock.code" :to="`/stock/${stock.code}`" class="stock-row" draggable="true" @dragstart="draggedCode = stock.code" @dragover.prevent @drop.prevent="dropStock(index)"><button v-if="editing" class="check" :class="{ checked: selected.includes(stock.code) }" @click.prevent.stop="toggle(stock.code)">{{ selected.includes(stock.code) ? '✓' : '' }}</button><span class="row-index">{{ String(index + 1).padStart(2, '0') }}</span><span class="stock-copy"><strong>{{ stock.name }}</strong><small>{{ stock.code }}</small></span><span class="stock-price mono">{{ stock.price }}</span><span class="stock-change mono" :class="quoteClass(stock)"><b>{{ stock.percent }}</b><small>{{ stock.change }}</small></span><span class="row-handle">⠿</span></RouterLink></div><EmptyState v-else title="这个分组还没有股票" message="从行情列表添加，或将其他分组的股票拖到左侧分组。" icon="☆" /></main></div>
    <div v-if="dialog" class="dialog-backdrop" @click.self="dialog = null"><form class="dialog" @submit.prevent="saveDialog"><button type="button" class="dialog-close" @click="dialog = null">×</button><p class="eyebrow">GROUP SETTINGS</p><h2>{{ dialog === 'create' ? '新建分组' : '重命名分组' }}</h2><label>分组名称<input v-model="draftName" autofocus maxlength="20" placeholder="例如：长期观察" /></label><div class="dialog-actions"><button type="button" @click="dialog = null">取消</button><button class="primary-small" type="submit">保存</button></div></form></div>
  </section>
</template>

<style scoped>
.groups-page{width:min(980px,100%);margin:0 auto;padding:0 0 30px;color:var(--text)}.page-head{display:flex;justify-content:space-between;padding:2px 2px 16px}.eyebrow{color:var(--primary);font:10px 'JetBrains Mono',monospace;letter-spacing:.12em}.page-head h1{margin-top:5px;font-size:23px}.subtitle{margin-top:6px;color:var(--muted);font-size:11px}.head-actions,.group-actions{display:flex;align-items:center;gap:8px}.source-badge{padding:6px 8px;border-radius:4px;background:#eaf8f1;color:#50a37d;font-size:9px}.source-badge.local{background:#f5f6f8;color:var(--muted)}.refresh{width:32px;height:32px;border:1px solid var(--border);border-radius:50%;background:var(--card);color:var(--primary);font-size:20px}.refresh:disabled{opacity:.5}.overview{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;margin-bottom:14px;border:1px solid var(--border);border-radius:7px;background:var(--border);overflow:hidden}.overview div{padding:13px 15px;background:var(--card)}.overview span,.overview strong{display:block}.overview span{color:var(--muted);font-size:10px}.overview strong{margin-top:7px;font:600 19px 'JetBrains Mono',monospace}.workspace{display:grid;grid-template-columns:285px minmax(0,1fr);gap:12px}.group-panel,.stock-panel{padding:16px;background:var(--card);border:1px solid var(--border);border-radius:7px}.panel-title,.stock-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:10px}.panel-title p{color:var(--primary);font:9px 'JetBrains Mono',monospace}.panel-title h2{margin-top:4px;font-size:16px}.primary-small{padding:7px 10px;border:0;border-radius:4px;background:var(--primary);color:#fff;font-size:10px}.drag-tip{margin:14px 0 7px;color:var(--muted);font-size:9px}.group-list{display:grid;gap:5px}.group-card{display:flex;align-items:center;width:100%;min-height:59px;padding:8px 7px;border:1px solid transparent;border-radius:5px;background:transparent;text-align:left;cursor:grab}.group-card:hover,.group-card.active{border-color:#dbe8fa;background:#f5f9ff}.drag-handle,.row-handle{color:#b1bac7;font-size:16px}.group-mark{display:grid;place-items:center;width:28px;height:28px;margin:0 9px;border-radius:7px;background:#edf4ff;color:var(--primary);font-size:16px}.group-copy{display:grid;gap:5px;min-width:0;flex:1}.group-copy strong{overflow:hidden;font-size:12px;text-overflow:ellipsis;white-space:nowrap}.group-copy small{color:var(--muted);font-size:9px}.group-copy i{font-style:normal}.group-arrow{color:#aab4c2;font-size:20px;font-weight:300}.market-link{display:block;margin:18px 0 2px;color:var(--primary);font-size:10px;text-align:center}.market-link span{font-size:17px;vertical-align:-1px}.stock-heading h2{margin-top:4px;font-size:17px}.stock-heading p:last-child{margin-top:7px;color:var(--muted);font-size:10px}.group-actions button,.toolbar button,.batch-bar button{padding:7px 9px;border:1px solid var(--border);border-radius:4px;background:var(--card);color:var(--primary);font-size:10px}.group-actions .danger,.danger{color:var(--down)}.toolbar{display:flex;align-items:center;gap:5px;margin-top:15px;border-bottom:1px solid var(--border)}.toolbar button{border:0;border-radius:4px 4px 0 0;color:var(--muted)}.toolbar button.active{background:#edf4ff;color:var(--primary);font-weight:600}.toolbar-note{margin-left:auto;color:var(--muted);font-size:9px}.batch-bar{display:flex;align-items:center;gap:9px;padding:8px 0;border-bottom:1px solid var(--border);color:var(--muted);font-size:10px}.batch-bar span{flex:1}.batch-bar button{border:0;padding:4px 0}.batch-bar select{max-width:125px;padding:5px;border:1px solid var(--border);border-radius:4px;background:var(--card);color:var(--muted);font-size:10px}.batch-bar button:disabled{opacity:.45}.stock-list{margin-top:2px}.stock-row{display:grid;grid-template-columns:20px 28px minmax(100px,1fr) 70px 75px 18px;gap:8px;align-items:center;min-height:65px;border-bottom:1px solid var(--border);color:inherit;text-decoration:none;cursor:grab}.stock-row:last-child{border-bottom:0}.row-index{color:#b3bac7;font:9px 'JetBrains Mono',monospace}.stock-copy{display:grid;gap:4px;min-width:0}.stock-copy strong{overflow:hidden;font-size:12px;text-overflow:ellipsis;white-space:nowrap}.stock-copy small,.stock-change small{color:var(--muted);font:9px 'JetBrains Mono',monospace}.stock-price,.stock-change{text-align:right;font-size:11px}.stock-change b,.stock-change small{display:block}.stock-change small{margin-top:4px}.check{width:18px;height:18px;padding:0;border:1px solid #cfd7e4;border-radius:50%;background:#fff;color:#fff;font-size:10px}.check.checked{border-color:var(--primary);background:var(--primary)}.text-up{color:var(--up)}.text-down{color:var(--down)}.error{padding:35px;text-align:center;color:var(--down);font-size:11px}.error button{border:0;background:transparent;color:var(--primary)}.dialog-backdrop{position:fixed;z-index:20;inset:0;display:grid;place-items:center;padding:20px;background:#20334d38}.dialog{position:relative;width:min(360px,100%);padding:22px;border-radius:8px;background:var(--card);box-shadow:0 10px 35px #20334d22}.dialog h2{margin-top:6px;font-size:17px}.dialog label{display:block;margin-top:18px;color:var(--muted);font-size:10px}.dialog input{display:block;width:100%;margin-top:7px;padding:10px;border:1px solid var(--border);border-radius:4px;outline:0;background:var(--bg);color:var(--text);font-size:12px}.dialog input:focus{border-color:var(--primary)}.dialog-close{position:absolute;top:12px;right:13px;border:0;background:transparent;color:var(--muted);font-size:21px}.dialog-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}.dialog-actions>button:first-child{padding:7px 10px;border:1px solid var(--border);border-radius:4px;background:var(--card);color:var(--muted);font-size:10px}
@media(max-width:700px){.groups-page{padding-top:0}.page-head{align-items:flex-start}.source-badge{display:none}.overview{margin-right:-1px;margin-left:-1px}.workspace{display:flex;flex-direction:column;gap:9px}.group-panel{padding:12px}.group-list{display:flex;overflow-x:auto;gap:7px;padding-bottom:2px}.group-card{min-width:155px}.market-link{margin:9px 0 0}.stock-panel{padding:13px 11px}.stock-heading{align-items:flex-start;flex-direction:column}.group-actions{width:100%;overflow-x:auto}.group-actions button{flex:1;white-space:nowrap}.toolbar{margin-top:11px}.stock-row{grid-template-columns:20px 25px minmax(80px,1fr) 58px 63px 15px;gap:5px;min-height:61px}.stock-copy strong{font-size:11px}.batch-bar{flex-wrap:wrap}.batch-bar span{min-width:70px}.batch-bar select{flex:1;max-width:none}}
@media(max-width:390px){.overview div{padding:11px 9px}.overview strong{font-size:16px}.overview span{font-size:9px}.stock-price{font-size:10px}.stock-change{font-size:10px}}
</style>